param([string]$OutputPath, [string]$PlanPath, [switch]$Execute, [string]$JournalPath, [string]$ConfirmPlanSha256, [switch]$AllowPush)
$ErrorActionPreference='Stop'; $repository=[System.IO.Path]::GetFullPath((Split-Path -Parent $PSScriptRoot)); $toolingRoot=[Environment]::GetEnvironmentVariable('RWT_CASCADE_TOOLING_ROOT'); if([string]::IsNullOrWhiteSpace($toolingRoot)){$toolingRoot='A:\Dev\RimWorld\Worktrees\RimWorld-Tooling\phase-a'}; $args=@('-Manifest',(Join-Path $repository 'Tools\CascadeManifest.json'),'-Repository',$repository); if($OutputPath){$args+=@('-OutputPath',$OutputPath)}; if($PlanPath){$args+=@('-PlanPath',$PlanPath)}; if($Execute){$args+=@('-Execute','-JournalPath',$JournalPath,'-ConfirmPlanSha256',$ConfirmPlanSha256);if($AllowPush){$args+='-AllowPush'}}; & powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File (Join-Path $toolingRoot 'tools\Invoke-RimWorldCascade.ps1') @args; exit $LASTEXITCODE
